Lemma qriSF_conc fx R M (V : nat -> Z) :
  0 <= (V 2%nat) < 2 ^ 64 -> 0 <= (V 34%nat) < 2 ^ 64 -> 0 <= (V 40%nat) < 2 ^ 64 -> 0 <= (V 41%nat) < 2 ^ 64 -> 0 <= (V 48%nat) < 2 ^ 64 ->
  getr R (reg 2) = Z_to_bv 64 ((V 2%nat) - 160) -> getr R (reg 10) = Z_to_bv 64 (V 40%nat) -> getr R (reg 11) = Z_to_bv 64 (V 41%nat) -> getr R (reg 21) = Z_to_bv 64 (V 34%nat) -> getr R (reg 23) = Z_to_bv 64 (V 48%nat) ->
  0 <= (V 48%nat) <= 31 -> 0 <= (V 41%nat) <= 31 ->
  exists fx' R' M', mem_grows M M'
    /\ (forall a : word, M' a = M a)
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
    /\ ((msteps RSEGS (st fx R 0xd0bd4 M) (st fx' R' 0xd3560 M')
        /\ (forall x, In x KS_qriSF_0 -> getr R' (reg x) = getr R (reg x))
        /\ getr R' (reg 1) = Z_to_bv 64 855012
        /\ getr R' (reg 11) = Z_to_bv 64 (V 48%nat)
        /\ getr R' (reg 24) = Z_to_bv 64 (V 40%nat)
        /\ (((V 41%nat) - (V 48%nat)) mod 2 ^ 64) < 1)
      \/ (msteps RSEGS (st fx R 0xd0bd4 M) (st fx' R' 0xc5ed8 M')
        /\ (forall x, In x KS_qriSF_1 -> getr R' (reg x) = getr R (reg x))
        /\ getr R' (reg 1) = Z_to_bv 64 855320
        /\ getr R' (reg 10) = Z_to_bv 64 (V 34%nat)
        /\ getr R' (reg 11) = Z_to_bv 64 1
